import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadSearchData(){const e=readFileSync(resolve(__dirname,"../../coin-search-and-advanced-filters/coin-search-data.js"),"utf-8");return new Function(e+"\nreturn { ALL_COINS_DATASET };")()}describe("Coin Search and Advanced Filters — Data Tests",()=>{let e;beforeAll(()=>{e=loadSearchData()}),describe("ALL_COINS_DATASET array",()=>{it("contains comprehensive coin dataset with all required filter fields",()=>{expect(Array.isArray(e.ALL_COINS_DATASET)).toBe(!0),expect(e.ALL_COINS_DATASET.length).toBeGreaterThanOrEqual(5),e.ALL_COINS_DATASET.forEach(e=>{expect(e.id).toBeDefined(),expect(e.name).toBeDefined(),expect(e.ruler).toBeDefined(),expect(e.period).toBeDefined(),expect(e.region).toBeDefined(),expect(e.metal).toBeDefined(),expect(e.script).toBeDefined(),expect(e.symbol).toBeDefined(),expect(e.coinType).toBeDefined()})}),it("supports filtering by Gold, Devanagari, and Maratha attributes",()=>{const t=e.ALL_COINS_DATASET.filter(e=>"Gold"===e.metal);expect(t.length).toBeGreaterThanOrEqual(2);const r=e.ALL_COINS_DATASET.filter(e=>"Devanagari"===e.script);expect(r.length).toBeGreaterThanOrEqual(2);const a=e.ALL_COINS_DATASET.filter(e=>e.ruler.includes("Maratha"));expect(a.length).toBeGreaterThanOrEqual(2)})})});